// 1. Obtener datos originales del Webhook
const raw = $('RECIBE_DATA').first().json.body || $('RECIBE_DATA').first().json;

// 2. Obtener respuesta del Nodo IA
let aiText = "";
try {
  const aiRes = $input.first().json;
  if (aiRes.candidates && aiRes.candidates[0] && aiRes.candidates[0].content && aiRes.candidates[0].content.parts) {
    aiText = aiRes.candidates[0].content.parts[0].text || "";
  } else if (raw.ai_summary) {
    aiText = raw.ai_summary;
  }
} catch (e) {
  aiText = raw.ai_summary || "";
}

// Función de sanitización antierrores HTML para Telegram
function stripHTML(text) {
  if (text === undefined || text === null) return "";
  return String(text)
    .replace(/<[^>]*>/g, "")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&")
    .trim();
}

// Mapeo inteligente de severidad
const sevUpper = String(raw.severidad || raw.severity || raw.nivel || "").toUpperCase();
let emoji = "⚠️";
if (sevUpper.includes("CRITIC") || sevUpper.includes("CRÍT")) emoji = "🚨";
else if (sevUpper.includes("HIGH") || sevUpper.includes("ALTA")) emoji = "🛑";
else if (sevUpper.includes("INFO") || sevUpper.includes("BAJ")) emoji = "ℹ️";
else if (sevUpper.includes("MED")) emoji = "🟡";

const severidad = stripHTML(raw.severidad || raw.severity || raw.nivel) || "INFO";
const score = stripHTML(raw.risk_score || raw.score || "N/A");
const evento = stripHTML(raw.tipo_incidente || raw.event_type || raw.evento || "Incidente de Ciberseguridad");
const activo = stripHTML(raw.activo_afectado || raw.affected_asset || raw.recurso) || "Infraestructura Alma";
const control = stripHTML(raw.control_nist || raw.framework_nist || raw.nist_control || raw.nist) || "NIST CSF v2.0";
const ip = stripHTML(raw.responsable_ip || raw.usuario_ip || raw.ip || raw.ip_origen) || "N/A";
const sop = stripHTML(raw.sop_reference || raw.regla || raw.sop);
const detalle = stripHTML(raw.detalles || raw.details || raw.descripcion) || "Sin detalles adicionales.";
const accionOriginal = stripHTML(raw.accion_recomendada || raw.suggested_action || raw.recomendacion) || "Verificar protocolos de seguridad.";
const aiClean = stripHTML(aiText);
const id = stripHTML(raw.incident_id || raw.id_incidente) || "N/A";
const timestamp = stripHTML(raw.timestamp || raw.fecha_hora) || new Date().toISOString();

let seccionSop = sop ? `• Procedimiento: ${sop}\n` : "";
let seccionTimestamp = timestamp ? ` | ${timestamp}` : "";

let seccionIa = "";
if (aiClean && aiClean.length > 5) {
  seccionIa = `\n🧠 TRIAGE EN TIEMPO REAL (NODO IA - Google Gemini):\n${aiClean}\n`;
}

const mensajeFinal = `
${emoji} [ALERTA DE CIBERSEGURIDAD - SOAR]

• Evento: ${evento}
• Severidad: ${severidad} (Score: ${score}/10)
• Activo: ${activo}
• Control NIST: ${control}
${seccionSop}• IP/Responsable: ${ip}
${seccionIa}
DETALLES TÉCNICOS:
${detalle}

ACCIÓN RECOMENDADA:
${accionOriginal}

⏱️ ID: ${id}${seccionTimestamp}
`.trim();

// Retornar tanto el texto formateado como el objeto estructurado para auditoría
return [{
  json: {
    text: mensajeFinal,
    incident_id: id,
    timestamp: timestamp,
    event_type: evento,
    severity: severidad,
    risk_score: score,
    affected_asset: activo,
    ip_source: ip,
    nist_control: control,
    sop_reference: sop || "SOP-04",
    ai_analysis: aiClean || "Análisis estándar aplicado",
    audit_status: "REGISTERED_NIST_DE_CM01"
  }
}];

// Módulo de Auditoría y Bitácora de Incidentes (NIST CSF v2.0: DE.CM-01 / Ley N° 29733)
const item = $input.first().json;

const logEntry = {
  registro_timestamp: new Date().toISOString(),
  id_incidente: item.incident_id,
  tipo_evento: item.event_type,
  severidad: item.severity,
  score_riesgo: item.risk_score,
  activo_custodiado: item.affected_asset,
  ip_origen: item.ip_source,
  control_aplicado: item.nist_control,
  procedimiento_sop: item.sop_reference,
  triage_ia_resultado: item.ai_analysis,
  cumplimiento_ley_29733: "TRAZABILIDAD_GARANTIZADA",
  estado_alerta: "DESPACHADA_A_TELEGRAM"
};

console.log("[AUDITORIA NIST DE.CM-01] Incidente registrado en bitacora:", JSON.stringify(logEntry));

return [{ json: logEntry }];
